// Traegt hier jeweils die Zeilen ein, deren contentStage manuell zurueckgesetzt werden soll.
// 2026-07-26 (3. Verwendung, erweitert): 2026/109 haengt bei contentStage=needs_content mit
// last_error_code CONTENT_JSON_INVALID (in Wahrheit: QA-Agent-Guard 'guard_sensitive_scene' -
// Kita-Kinder als Bild-Pointe). Auf Nutzerwunsch: komplette Neuauflage der Satire-Variante statt
// nur Retry. Reset auf needs_summary allein reicht nicht - P3s "Speichere Analyse" setzt weder
// judgmentChainProcessedAt noch headlineChoiceStage zurueck, beide muessen hier explizit leer
// werden, sonst ueberspringen P3d (Agenten-Kette) und P3e (Satire-Agent) die Zeile weiterhin
// wegen ihrer Guard-Bedingungen (judgmentChainProcessedAt muss leer sein, headlineChoiceStage
// muss leer/'needs_kernbotschaft' sein).
const TARGETS = [
  { vorgangKey: 'vol_10600', vorgangsnummer: '2026/109', targetStage: 'needs_summary' }
];

if (!TARGETS.length) {
  throw new Error('[ContentStage-Reset] TARGETS im Node "Konfiguriere Ziele" befuellen.');
}

return TARGETS.map(t => ({
  json: {
    vorgangKey: t.vorgangKey,
    vorgangsnummer: t.vorgangsnummer,
    contentStage: t.targetStage || 'needs_summary',
    headlineChoiceStage: '',
    visualPromptStage: '',
    judgmentChainProcessedAt: '',
    imageHeadline: '',
    imageSubline: '',
    contentErrorReason: '',
    last_error_code: '',
    last_error_message: '',
    last_error_stage: '',
    last_error_at: '',
    next_retry_at: '',
    retry_count: 0
  }
}));
